import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Basic Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basic-syntax.md","filePath":"guide/basic-syntax.md","lastUpdated":1781686130000}'),n={name:"guide/basic-syntax.md"};function d(o,e,l,r,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="basic-syntax" tabindex="-1">Basic Syntax <a class="header-anchor" href="#basic-syntax" aria-label="Permalink to “Basic Syntax”">​</a></h1><p>This chapter covers the fundamental building blocks of NG: comments, variables, data types, operators, and expressions.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h2><p>NG supports single-line comments only:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// This is a comment.</span></span>
<span class="line"><span>// Comments start with</span><span> // and extend to the end of the line.</span></span></code></pre></div><p>There is no multi-line <code>/* ... */</code> syntax.</p><h2 id="variables-and-mutability" tabindex="-1">Variables and Mutability <a class="header-anchor" href="#variables-and-mutability" aria-label="Permalink to “Variables and Mutability”">​</a></h2><p>Variables are declared with the <code>val</code> keyword. By default, variables are <strong>mutable</strong> — you can reassign them:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 1;   // x is 1</span></span>
<span class="line"><span>x = 2;       // now x is 2</span></span></code></pre></div><h3 id="immutability" tabindex="-1">Immutability <a class="header-anchor" href="#immutability" aria-label="Permalink to “Immutability”">​</a></h3><p>The language currently has no <code>const</code> or <code>let</code> distinction — all <code>val</code> bindings are mutable. If you need a value that shouldn&#39;t change, it&#39;s a convention not to reassign it.</p><h3 id="type-annotations" tabindex="-1">Type Annotations <a class="header-anchor" href="#type-annotations" aria-label="Permalink to “Type Annotations”">​</a></h3><p>You can explicitly annotate the type:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x: i32 = 1;</span></span>
<span class="line"><span>val name: string = &quot;NG&quot;;</span></span>
<span class="line"><span>val flag: bool = true;</span></span>
<span class="line"><span>val pi: f64 = 3.14159;</span></span></code></pre></div><p>If you omit the annotation, the type is <strong>inferred</strong> from the initializer. Numeric literals default to <code>i32</code> (integer) or <code>f32</code> (floating):</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = 42;      // a is i32</span></span>
<span class="line"><span>val b = 3.14;    // b is f32</span></span></code></pre></div><h2 id="primitive-data-types" tabindex="-1">Primitive Data Types <a class="header-anchor" href="#primitive-data-types" aria-label="Permalink to “Primitive Data Types”">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>i8</code>, <code>i16</code>, <code>i32</code>, <code>i64</code></td><td>Signed integers</td><td><code>-42</code>, <code>0xFF</code>, <code>0b1010</code></td></tr><tr><td><code>u8</code>, <code>u16</code>, <code>u32</code>, <code>u64</code></td><td>Unsigned integers</td><td><code>42u</code>, <code>0xFEu8</code></td></tr><tr><td><code>f32</code>, <code>f64</code></td><td>Floating-point numbers</td><td><code>3.14</code>, <code>1.0e-10f64</code></td></tr><tr><td><code>bool</code></td><td>Boolean</td><td><code>true</code>, <code>false</code></td></tr><tr><td><code>string</code></td><td>UTF-8 string</td><td><code>&quot;hello&quot;</code>, <code>&#39;world&#39;</code></td></tr><tr><td><code>unit</code></td><td>No value</td><td><code>unit</code> (like <code>void</code> in C)</td></tr></tbody></table><h3 id="numeric-literals" tabindex="-1">Numeric Literals <a class="header-anchor" href="#numeric-literals" aria-label="Permalink to “Numeric Literals”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = 42;          // i32</span></span>
<span class="line"><span>val b = 42u16;       // u16 (suffix)</span></span>
<span class="line"><span>val c = -128i8;      // explicit i8</span></span>
<span class="line"><span>val d = 0xFF;        // hexadecimal → i32</span></span>
<span class="line"><span>val e = 0b1010;      // binary → i32</span></span>
<span class="line"><span>val f = 3.14;        // f32 (default float)</span></span>
<span class="line"><span>val g = 3.14f64;     // f64</span></span>
<span class="line"><span>val h = 1.0e10;      // scientific notation</span></span></code></pre></div><h3 id="string-literals" tabindex="-1">String Literals <a class="header-anchor" href="#string-literals" aria-label="Permalink to “String Literals”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val s1 = &quot;double quoted&quot;;</span></span>
<span class="line"><span>val s2 = &#39;single quoted&#39;;</span></span>
<span class="line"><span>val s3 = &quot;escape sequences: \\n \\t \\\\ \\&quot;&quot;;</span></span></code></pre></div><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to “Operators”">​</a></h2><h3 id="arithmetic" tabindex="-1">Arithmetic <a class="header-anchor" href="#arithmetic" aria-label="Permalink to “Arithmetic”">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th></tr></thead><tbody><tr><td><code>+</code></td><td>Addition / string concatenation</td></tr><tr><td><code>-</code></td><td>Subtraction / negation</td></tr><tr><td><code>*</code></td><td>Multiplication</td></tr><tr><td><code>/</code></td><td>Division</td></tr><tr><td><code>%</code></td><td>Modulo</td></tr></tbody></table><h3 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to “Comparison”">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th></tr></thead><tbody><tr><td><code>==</code></td><td>Equal</td></tr><tr><td><code>!=</code></td><td>Not equal</td></tr><tr><td><code>&gt;</code></td><td>Greater than</td></tr><tr><td><code>&lt;</code></td><td>Less than</td></tr><tr><td><code>&gt;=</code></td><td>Greater than or equal</td></tr><tr><td><code>&lt;=</code></td><td>Less than or equal</td></tr></tbody></table><h3 id="logical" tabindex="-1">Logical <a class="header-anchor" href="#logical" aria-label="Permalink to “Logical”">​</a></h3><p>There are no <code>&amp;&amp;</code> or <code>||</code> operators. Use functions from the standard prelude:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val result = not(x &gt; 0);   // logical NOT</span></span></code></pre></div><h3 id="other-operators" tabindex="-1">Other Operators <a class="header-anchor" href="#other-operators" aria-label="Permalink to “Other Operators”">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>&lt;&lt;</code></td><td>Array append</td><td><code>arr &lt;&lt; 6</code></td></tr><tr><td><code>is</code></td><td>Type check</td><td><code>x is i32</code></td></tr><tr><td><code>|&gt;</code></td><td>Pipe forward</td><td><code>value |&gt; transform</code></td></tr><tr><td><code>..</code></td><td>Range (exclusive end)</td><td><code>0..10</code></td></tr><tr><td><code>..=</code></td><td>Range (inclusive end)</td><td><code>0..=10</code></td></tr><tr><td><code>...</code></td><td>Spread / pack expansion</td><td><code>...args</code></td></tr><tr><td><code>.</code></td><td>Property/method access</td><td><code>obj.field</code></td></tr><tr><td><code>=</code></td><td>Assignment</td><td><code>x = 42</code></td></tr><tr><td><code>:=</code></td><td>Deref assignment</td><td><code>*ptr := value</code></td></tr></tbody></table><h3 id="pipe-forward-operator" tabindex="-1">Pipe Forward Operator <a class="header-anchor" href="#pipe-forward-operator" aria-label="Permalink to “Pipe Forward Operator”">​</a></h3><p>The <code>|&gt;</code> operator pipes a value into a function call:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun double(x: i32) -&gt; i32 =&gt; x * 2;</span></span>
<span class="line"><span>fun inc(x: i32) -&gt; i32 =&gt; x + 1;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val result = 5 |&gt; inc |&gt; double;  // 12 (same as double(inc(5)))</span></span></code></pre></div><h2 id="expressions-and-statements" tabindex="-1">Expressions and Statements <a class="header-anchor" href="#expressions-and-statements" aria-label="Permalink to “Expressions and Statements”">​</a></h2><p>NG is <strong>expression-oriented</strong> — most constructs produce values. A <strong>statement</strong> is terminated by <code>;</code> and does not produce a value.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 42;          // statement</span></span>
<span class="line"><span>val y = x + 1;       // expression (x + 1) assigned to y</span></span></code></pre></div><h2 id="blocks-and-scope" tabindex="-1">Blocks and Scope <a class="header-anchor" href="#blocks-and-scope" aria-label="Permalink to “Blocks and Scope”">​</a></h2><p>A block <code>{ ... }</code> groups statements and creates a new scope. Variables declared inside a block are not visible outside it.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val outer = 1;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    val inner = 2;    // only visible inside this block</span></span>
<span class="line"><span>    outer = inner;    // OK: outer is in scope</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// inner is not accessible here</span></span></code></pre></div><h2 id="unit-type" tabindex="-1">Unit Type <a class="header-anchor" href="#unit-type" aria-label="Permalink to “Unit Type”">​</a></h2><p>The <code>unit</code> type represents the absence of a value. It is analogous to <code>void</code> in C or <code>None</code> in Python. Functions that don&#39;t return a value implicitly return <code>unit</code>.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val nothing = unit;   // nothing has type unit</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Now that you understand the basics, move on to <a href="./control-flow">Control Flow</a> to learn about conditionals and loops.</p><blockquote><p><strong>Try it:</strong> <code>example/02.many_defs.ng</code> — Multiple definitions and basic expressions <strong>Try it:</strong> <code>example/05.valdef.ng</code> — Value definitions and type annotations</p></blockquote>`,47)])])}const b=a(n,[["render",d]]);export{g as __pageData,b as default};
